[CmdletBinding()]
param([string]$OutputRoot)

$ErrorActionPreference='Stop'
$repoRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'))
$goBackend=Join-Path $repoRoot 'go-backend';$dataRoot=Join-Path $goBackend 'input_methods\yime\data';$sourceRoot=Join-Path $repoRoot 'YimeTextServiceExperiment'
$allowedRoot=[IO.Path]::GetFullPath((Join-Path $repoRoot '.tmp\yimecore-experiment'))
if([string]::IsNullOrWhiteSpace($OutputRoot)){$OutputRoot=Join-Path $allowedRoot ('e6b2b\'+(Get-Date -Format 'yyyyMMdd-HHmmss'))}
$outputDir=[IO.Path]::GetFullPath($OutputRoot);$prefix=$allowedRoot.TrimEnd([IO.Path]::DirectorySeparatorChar)+[IO.Path]::DirectorySeparatorChar
if($outputDir -ne $allowedRoot -and -not $outputDir.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw "E6-B2b evidence must stay under $allowedRoot"}
New-Item -ItemType Directory -Force $outputDir|Out-Null;$bin=Join-Path $outputDir 'bin';New-Item -ItemType Directory -Force $bin|Out-Null
$broker=Join-Path $bin 'YimeBroker.exe';$indexTool=Join-Path $bin 'yimecore-index.exe'
Push-Location $goBackend
try{& go test ./input_methods/yime/yimebroker ./cmd/yimebroker -count=1 2>&1|Tee-Object -FilePath (Join-Path $outputDir 'go-test.txt');if($LASTEXITCODE){throw 'Go tests failed'};& go build -trimpath -o $broker ./cmd/yimebroker;if($LASTEXITCODE){throw 'Broker build failed'};& go build -trimpath -o $indexTool ./cmd/yimecore-index;if($LASTEXITCODE){throw 'Index build failed'}}finally{Pop-Location}

$artifacts=[ordered]@{};$architectures=@()
foreach($a in @([ordered]@{name='x64';cmake='x64';bits=64},[ordered]@{name='x86';cmake='Win32';bits=32})){
 $build=Join-Path $outputDir ('build-'+$a.name);& cmake -S $sourceRoot -B $build -A $a.cmake 2>&1|Tee-Object -FilePath (Join-Path $outputDir ('configure-'+$a.name+'.txt'));if($LASTEXITCODE){throw "$($a.name) configure failed"};& cmake --build $build --config Release 2>&1|Tee-Object -FilePath (Join-Path $outputDir ('build-'+$a.name+'.txt'));if($LASTEXITCODE){throw "$($a.name) build failed"};& ctest --test-dir $build -C Release --output-on-failure 2>&1|Tee-Object -FilePath (Join-Path $outputDir ('b1-regression-'+$a.name+'.txt'));if($LASTEXITCODE){throw "$($a.name) B1 regression failed"}
 $dll=Join-Path $build 'Release\YimeTextServiceExperiment.dll';$test=Join-Path $build 'Release\YimeTsfCompositionTests.exe';$artifacts[$a.name]=[ordered]@{dll=$dll;test=$test};$architectures+=[ordered]@{architecture=$a.name;bits=$a.bits;dll_sha256=(Get-FileHash $dll -Algorithm SHA256).Hash.ToLowerInvariant();test_sha256=(Get-FileHash $test -Algorithm SHA256).Hash.ToLowerInvariant()}
}
function Start-Broker([string]$index,[string]$mode,[string]$pipe,[string]$log){Start-Process -FilePath $broker -ArgumentList @('-index',$index,'-mode',$mode,'-named-pipe',$pipe) -PassThru -WindowStyle Hidden -RedirectStandardError $log}
function Stop-Broker([Diagnostics.Process]$p){if($p -and -not $p.HasExited){Stop-Process -Id $p.Id -Force;$p.WaitForExit()}}
$modes=@([ordered]@{mode='full';source='yime_full.dict.yaml'},[ordered]@{mode='variable';source='yime_variable.dict.yaml'},[ordered]@{mode='shorthand';source='yime_shorthand.dict.yaml'});$modeResults=@()
foreach($definition in $modes){
 $modeDir=Join-Path $outputDir $definition.mode;New-Item -ItemType Directory -Force $modeDir|Out-Null;$index=Join-Path $modeDir 'index.yidx';$manifest=Join-Path $modeDir 'index-build.json';& $indexTool -mode $definition.mode -source (Join-Path $dataRoot $definition.source) -output $index -manifest $manifest -allowed-source-root $dataRoot -allowed-output-root $outputDir;if($LASTEXITCODE){throw "$($definition.mode) index failed"};$build=Get-Content $manifest -Raw|ConvertFrom-Json;$pipe="\\.\pipe\YimeBroker-e6b2b-$($definition.mode)-$PID";$p=Start-Broker $index $definition.mode $pipe (Join-Path $modeDir 'broker-before.err');$runs=@()
 try{foreach($a in @('x64','x86')){$timer=[Diagnostics.Stopwatch]::StartNew();$text=& $artifacts[$a].test $artifacts[$a].dll $pipe 2>&1;$timer.Stop();$text|Set-Content (Join-Path $modeDir ($a+'.txt')) -Encoding utf8;if($LASTEXITCODE){throw "$($definition.mode) $a TSF test failed: $text"};$runs+=[ordered]@{architecture=$a;elapsed_ms=$timer.Elapsed.TotalMilliseconds;passed=$true}}}finally{Stop-Broker $p}
 $restart=[Diagnostics.Stopwatch]::StartNew();$p=Start-Broker $index $definition.mode $pipe (Join-Path $modeDir 'broker-after.err');try{$text=& $artifacts.x64.test $artifacts.x64.dll $pipe 2>&1;if($LASTEXITCODE){throw "$($definition.mode) restart TSF test failed: $text"}}finally{Stop-Broker $p;$restart.Stop()}
 $modeResults+=[ordered]@{mode=$definition.mode;source_sha256=$build.build.source_sha256;index_sha256=$build.build.index_sha256;index_verified=[bool]$build.verified;runs=$runs;restart_recovery_ms=$restart.Elapsed.TotalMilliseconds;passed=([bool]$build.verified -and $restart.ElapsedMilliseconds -lt 2000)}
}
$sourceFiles=@('docs\project\YIMECORE_REPLACEMENT_EXPERIMENT.md','YimeTextServiceExperiment\CMakeLists.txt','YimeTextServiceExperiment\BrokerClient.h','YimeTextServiceExperiment\BrokerClient.cpp','YimeTextServiceExperiment\CandidateListUIElement.h','YimeTextServiceExperiment\CandidateListUIElement.cpp','YimeTextServiceExperiment\CandidatePopup.h','YimeTextServiceExperiment\CandidatePopup.cpp','YimeTextServiceExperiment\CompositionEditSession.h','YimeTextServiceExperiment\CompositionEditSession.cpp','YimeTextServiceExperiment\ExperimentSettings.h','YimeTextServiceExperiment\ExperimentSettings.cpp','YimeTextServiceExperiment\KeyContract.h','YimeTextServiceExperiment\KeyContract.cpp','YimeTextServiceExperiment\SurfaceSession.h','YimeTextServiceExperiment\SurfaceSession.cpp','YimeTextServiceExperiment\TextService.h','YimeTextServiceExperiment\TextService.cpp','YimeTextServiceExperiment\tests\TsfCompositionTests.cpp','tools\yimecore\run-e6b2b-tsf-composition-experiment.ps1')
$hashes=foreach($relative in $sourceFiles){$hash=Get-FileHash (Join-Path $repoRoot $relative) -Algorithm SHA256;[ordered]@{path=$relative.Replace('\','/');sha256=$hash.Hash.ToLowerInvariant()}};$sourceHashes=Join-Path $outputDir 'source-hashes.json';$hashes|ConvertTo-Json -Depth 3|Set-Content $sourceHashes -Encoding utf8
$summary=[ordered]@{tool_version='yime-text-service-e6b2b-tsf-composition-v1';stage='e6b2b';generated_at=(Get-Date).ToUniversalTime().ToString('o');git_commit=(& git -C $repoRoot rev-parse HEAD).Trim();git_dirty=[bool]((& git -C $repoRoot status --porcelain).Count);go_version=(& go version).Trim();os_arch='windows/'+$env:PROCESSOR_ARCHITECTURE.ToLowerInvariant();source_boundary=$dataRoot;output_boundary=$outputDir;broker_sha256=(Get-FileHash $broker -Algorithm SHA256).Hash.ToLowerInvariant();architectures=$architectures;modes=$modeResults;all_indices_verified=-not($modeResults.index_verified -contains $false);all_modes_passed=-not($modeResults.passed -contains $false);real_itfcontext_edit_sessions=$true;raw_composition_progression_verified=$true;stable_candidate_commit_verified=$true;invalid_code_candidate_ui_preserved=$true;backspace_state_sync_verified=$true;deleted_code_resurrection_blocked=$true;direction_and_page_keys_verified=$true;normal_commit_preserves_broker_session=$true;composition_termination_verified=$true;edit_failure_policy='close experimental Broker session and report key not eaten';direct_test_key_sink_bypass=$true;registered_key_sink_verified=$false;restart_within_two_seconds=-not(($modeResults|Where-Object{$_.restart_recovery_ms -ge 2000}).Count);registry_or_installation_changed=$false;source_hashes_sha256=(Get-FileHash $sourceHashes -Algorithm SHA256).Hash.ToLowerInvariant();limitations=@('ITfContext edit sessions are real, but the unregistered test DLL uses an explicit direct-test bypass instead of AdviseKeyEventSink','candidate UI, language bar, focus loss, registered host callbacks and installation remain later E6 gates')}
$summaryPath=Join-Path $outputDir 'summary.json';$summary|ConvertTo-Json -Depth 8|Set-Content $summaryPath -Encoding utf8;Write-Host "YimeTextService E6-B2b evidence: $outputDir";if(-not $summary.all_indices_verified -or -not $summary.all_modes_passed -or -not $summary.restart_within_two_seconds -or $summary.registry_or_installation_changed){throw "E6-B2b gate failed; see $summaryPath"}
